head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil15800";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil15800.onpageload' });
    }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "ipt_keyword", fn: function () { return String((dma_pageContext.get("keyword") ?? "")); } },
        { childId: "__rb0", fn: function () { return " 전체 " + String(dma_page.get("total")) + "건 (" + String(dma_page.get("currentPage")) + "/" + String(dma_page.get("pageCount")) + " 페이지) "; } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

// [A] 초기 목록 미해결 — jldfil15800: 진입 키 report 는 알지만 그 URL 을 쓰는 tx 가 화면에 없다(URL 을 지어내지 않는다) · 자기 목록 tx 0

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_48_onclick
 * @description img_48 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_48_onclick = async function(e){
    try {
        await scwin.search()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil15800.img_48_onclick' }); }
};

/**
 * @method
 * @name slc_pageSize_onchange
 * @description slc_pageSize 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.slc_pageSize_onchange = async function(e){
    try {
        await scwin.search();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil15800.slc_pageSize_onchange' }); }
};

/**
 * @method
 * @name grd_krpReportList_oncellclick
 * @description grd_krpReportList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_krpReportList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_krpReportList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_krpReportList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (r["fileSurFix"] != null && r["fileSurFix"] !== '') { await scwin.downKrpFile(r["realName"], r["fileName"], r["fileDir"]); return; }
        await scwin.searchDetail(r["isuSrtCd"], r["bycorpSeq"], r["partcYy"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_krpReportList.oncellclick' });
    }
};

/**
 * @method
 * @name krxpage_pagenavigator_108_onclick
 * @description krxpage_pagenavigator_108 클릭 이벤트
 * @param {Number} index index
 * @returns {void}
 * @hidden N
 */
scwin.krxpage_pagenavigator_108_onclick = async function (index) {
    try {
        const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index;
        $c.util.getComponent('dma_SearchReq').set('pageIndex', pi);
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldfil15800.krxpage_pagenavigator_108_onclick" });
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name tx_fn_Search
 * @description Search 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Search = async function (action) {
    try { return await $c.data.downFile(action ?? "/support/report.do", "", ($c.util.getComponent("dma_SearchReq") ? $c.util.getComponent("dma_SearchReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name tx_fn_SearchDetail
 * @description Search Detail 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_SearchDetail = async function (action) {
    try { return await $c.data.downFile(action ?? "/support/report.do", "", ($c.util.getComponent("dma_SearchDetailReq") ? $c.util.getComponent("dma_SearchDetailReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name tx_fn_DownKrpFile
 * @description Down Krp File 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_DownKrpFile = async function () {
    try { return await $c.data.downFile("http://www.krx.co.kr/servlets/exkrx/util/Download", "", ($c.util.getComponent("dma_DownKrpFileReq") ? $c.util.getComponent("dma_DownKrpFileReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function () {
    $c.util.getComponent('dma_SearchReq').set('method', 'searchKrpReport');
    await scwin.tx_fn_Search('report.do');
};

/**
 * @method
 * @name searchDetail
 * @description search Detail 처리
 * @param {String} _isurCd _isurCd
 * @param {*} _bycorpSeq _bycorpSeq
 * @param {*} _partcYy _partcYy
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchDetail = async function (_isurCd, _bycorpSeq, _partcYy) {
    $c.util.getComponent('dma_SearchReq').set('method', 'searchKrpReportDetail');
    $c.util.getComponent('dma_SearchReq').set('isurCd', _isurCd);
    $c.util.getComponent('dma_SearchReq').set('bycorpSeq', _bycorpSeq);
    $c.util.getComponent('dma_SearchReq').set('partcYy', _partcYy);
    await scwin.tx_fn_SearchDetail('report.do');
};

/**
 * @method
 * @name downKrpFile
 * @description down Krp File 처리
 * @param {*} _realName _realName
 * @param {*} _fileName _fileName
 * @param {*} _fileDir _fileDir
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.downKrpFile = async function (_realName, _fileName, _fileDir) {
    $c.util.getComponent('dma_SearchReq').set('fileName', _fileName);
    $c.util.getComponent('dma_SearchReq').set('realName', _realName);
    $c.util.getComponent('dma_SearchReq').set('fileDir', _fileDir);
    await scwin.tx_fn_DownKrpFile();
};
